// Hand-written types + calls for the M1 endpoints described in docs/API_CONTRACT.md.
// TODO(lead): reconcile with the generated OpenAPI types (`npm run gen:api`) once the engine exposes them.
//
// Dev-only mock: `npm run dev -- --mode mock` swaps every call for the synthetic phantom in `mock.ts`
// (data generated by `node scripts/make-mock-study.mjs`). The mock module is tree-shaken from real builds.
import { api, watchJob, type JobInfo, type ProgressEvent } from './client'

export type { JobInfo, ProgressEvent }

export const MOCK = import.meta.env.MODE === 'mock'
const mock = () => import('./mock')

// ---------- §1 choosing what to import ----------
export type FsRootKind = 'drive' | 'home' | 'removable' | 'recent'
export interface FsRoot { path: string; label: string; kind: FsRootKind }
export type FsHint = 'dicomdir' | 'dcmburner' | 'radiant' | (string & {})
export interface FsEntry { name: string; path: string; kind: 'dir' | 'file'; size: number | null; hint?: FsHint | null }
export interface FsListing { path: string; parent: string | null; entries: FsEntry[] }
export interface InspectResult { adapter: string | null; label: string; encrypted: boolean; confidence: number; notes: string[] }

// ---------- §2 import job ----------
export interface ImportRequest { path: string; password?: string; remember?: boolean }
export type ImportErrorCode = 'password_required' | 'wrong_password' | 'no_images' | 'unsupported' | 'too_large'
export const IMPORT_STAGES = ['detect', 'decrypt', 'extract', 'scan', 'group', 'classify', 'export'] as const
export type ImportStage = (typeof IMPORT_STAGES)[number]

// ---------- §3 study ----------
export type Plane = 'axial' | 'sagittal' | 'coronal' | 'oblique' | 'projection' | 'unknown'
export type Role = 'primary' | 'derived' | 'mip' | 'localizer' | 'photo' | 'document'
export type Region = 'brain' | 'spine' | 'chest' | 'abdomen' | 'limb' | 'vessels' | 'unknown'

export interface SeriesInfo {
  id: string
  modality: string
  description: string
  body_part: string
  plane: Plane
  sequence: string
  role: Role
  n_images: number
  rows: number
  cols: number
  pixel_spacing: [number, number] | null
  slice_thickness: number | null
}

export interface StudyInfo {
  id: string
  adapter: string
  display_name: string
  study_date: string
  description: string
  modalities: string[]
  series: SeriesInfo[]
  warnings: string[]
}

export interface StudySummary {
  id: string
  description: string
  study_date: string
  modalities: string[]
  n_series?: number
  adapter?: string
}

/** `series/{id}/meta.json` — the slice-stack artifact. */
export interface SeriesMeta {
  id: string
  title: string
  modality: string
  sequence: string
  plane: Plane | 'mip' | string
  region: Region | string
  role: Role | string
  n: number
  ext: string
  w: number
  h: number
  rows: number
  cols: number
  /** DICOM order [row, col] mm; null for photos / PDF pages. */
  pixelSpacing: [number, number] | null
  thickness: number | null
  TE?: number | null
  TR?: number | null
  seriesNumber?: number | null
  desc?: string
  orientation: number[] | null
  slices: { pos: [number, number, number] | null }[]
  window?: { lo: number; hi: number }
  labels: boolean
  /** Not in contract v1: optional code → name map. Real names arrive with M2 atlases. */
  labelNames?: Record<string, string>
}

// ---------- calls ----------
const enc = encodeURIComponent

export async function fsRoots(): Promise<FsRoot[]> {
  return MOCK ? (await mock()).mockRoots() : api.get<FsRoot[]>('/api/fs/roots')
}
export async function fsList(path: string): Promise<FsListing> {
  return MOCK ? (await mock()).mockList(path) : api.get<FsListing>(`/api/fs/list?path=${enc(path)}`)
}
export async function inspect(path: string): Promise<InspectResult> {
  return MOCK ? (await mock()).mockInspect(path) : api.post<InspectResult>('/api/inspect', { path })
}
export async function startImport(body: ImportRequest): Promise<JobInfo> {
  return MOCK ? (await mock()).mockImport(body) : api.post<JobInfo>('/api/import', body)
}
export async function cancelJob(id: string): Promise<void> {
  if (MOCK) return (await mock()).mockCancel(id)
  await api.cancelJob(id)
}
/** Subscribe to job progress (SSE). Returns an unsubscribe function. */
export function watch(id: string, onEvent: (e: ProgressEvent) => void, onEnd: (j: JobInfo) => void): () => void {
  if (!MOCK) return watchJob(id, onEvent, onEnd)
  let stop: (() => void) | null = null
  let dead = false
  mock().then((m) => { if (!dead) stop = m.mockWatch(id, onEvent, onEnd) })
  return () => { dead = true; stop?.() }
}

export async function listStudies(): Promise<StudySummary[]> {
  return MOCK ? (await mock()).mockStudies() : api.get<StudySummary[]>('/api/studies')
}
export async function getStudy(id: string): Promise<StudyInfo> {
  return MOCK ? (await mock()).mockStudy(id) : api.get<StudyInfo>(`/api/studies/${enc(id)}`)
}
export async function deleteStudy(id: string): Promise<void> {
  if (MOCK) return
  await api.del(`/api/studies/${enc(id)}`)
}

/** URL of a study artifact file (`relpath` like `series/s003/meta.json`). */
export function fileUrl(studyId: string, relpath: string): string {
  const rel = relpath.split('/').map(enc).join('/')
  return MOCK ? `/mock/studies/${enc(studyId)}/files/${rel}` : `/api/studies/${enc(studyId)}/files/${rel}`
}
/** Image file name for slice `i` (`000.webp`) or its label map (`L000.png`). */
export const sliceName = (i: number, ext: string) => `${String(i).padStart(3, '0')}.${ext}`
export const labelName = (i: number) => `L${String(i).padStart(3, '0')}.png`

const metaCache = new Map<string, Promise<SeriesMeta>>()
export function getSeriesMeta(studyId: string, seriesId: string): Promise<SeriesMeta> {
  const url = fileUrl(studyId, `series/${seriesId}/meta.json`)
  let p = metaCache.get(url)
  if (!p) {
    p = fetch(url, { credentials: 'same-origin' }).then((r) => {
      if (!r.ok) throw new Error(`meta ${r.status}`)
      return r.json() as Promise<SeriesMeta>
    })
    p.catch(() => metaCache.delete(url))
    metaCache.set(url, p)
  }
  return p
}
